import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void basicos() {
        assertEquals(1024.0, Solution.pow(2.0, 10), 1e-9);
        assertEquals(9.261, Solution.pow(2.1, 3), 1e-9);
        assertEquals(0.25, Solution.pow(2.0, -2), 1e-12);
        assertEquals(1.0, Solution.pow(123.0, 0));
    }

    @Test void minValue() {
        assertEquals(0.0, Solution.pow(2.0, Integer.MIN_VALUE), 1e-300);
        assertEquals(1.0, Solution.pow(1.0, Integer.MIN_VALUE));
        assertEquals(1.0, Solution.pow(-1.0, Integer.MIN_VALUE));
    }

    @Test void rapidoComExpoenteEnorme() {
        assertEquals(1.0, Solution.pow(-1.0, Integer.MAX_VALUE) * -1, 0);
        double esperado = Math.pow(1.0000001, 2_000_000_000);
        assertEquals(esperado, Solution.pow(1.0000001, 2_000_000_000), esperado * 1e-6);
    }
}

