public class Solution {
    static final long MOD = 1_000_000_007L;

    static long modPow(long b, long e, long mod) {
        b %= mod;
        if (b < 0) b += mod;
        long r = 1 % mod;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % mod;
            b = b * b % mod;
            e >>= 1;
        }
        return r;
    }

    // Pequeno teorema de Fermat: a^(p-1) ≡ 1, então a^(p-2) é o inverso (se p não divide a).
    static long inverso(long a) {
        long r = ((a % MOD) + MOD) % MOD;
        if (r == 0) throw new IllegalArgumentException("sem inverso");
        return modPow(r, MOD - 2, MOD);
    }

    static long mediaMod(long[] valores) {
        long soma = 0;
        for (long v : valores) soma = (soma + ((v % MOD) + MOD) % MOD) % MOD;
        return soma * inverso(valores.length) % MOD;
    }
}

