import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void inversoMultiplicaParaUm() {
        for (long a : new long[]{1, 2, 3, 999_999_999, 123_456_789_012L, -5}) {
            long inv = Solution.inverso(a);
            long norm = ((a % Solution.MOD) + Solution.MOD) % Solution.MOD;
            assertEquals(1, norm * inv % Solution.MOD, "a = " + a);
        }
        assertEquals(500_000_004, Solution.inverso(2));
    }

    @Test void semInverso() {
        assertThrows(IllegalArgumentException.class, () -> Solution.inverso(0));
        assertThrows(IllegalArgumentException.class, () -> Solution.inverso(Solution.MOD * 3));
    }

    @Test void media() {
        assertEquals(2, Solution.mediaMod(new long[]{1, 2, 3}));
        assertEquals(500_000_004, Solution.mediaMod(new long[]{0, 1}));     // 1/2
        assertEquals(Solution.MOD - 1, Solution.mediaMod(new long[]{-1, -1}));
    }

    @Test void modPowGrande() {
        assertEquals(1, Solution.modPow(5, Solution.MOD - 1, Solution.MOD));
        assertEquals(0, Solution.modPow(7, 3, 1));
    }
}
